// 原Task/Q01、实物与完整Family控制先验之后核销约；实际提交尾先绑Common结果再做全史。
#include "task_personal_cancellation_world.hpp"
#include "task_personal_cancellation_control.hpp"
#include "resident/kernel/world_bundle.hpp"
#include "resident/kernel/political_takeover_execution_world.hpp"
namespace hanmo::resident {namespace {
const TaskPersonalCancellationState* state(const WorldBundle& w){return w.tasks.personal_cancellations?&*w.tasks.personal_cancellations:nullptr;}
Status ready(const WorldBundle& w){if(!w.dynamic_enabled()||!w.catalog->task_personal_cancellations||!w.catalog->task_personal_messages||!w.tasks.personal_messages||!w.catalog->tasks||!w.tasks.message_handoffs||(w.catalog->task_message_handoff_version!=3&&w.catalog->task_message_handoff_version!=4)||w.tasks.message_handoffs->version!=w.catalog->task_message_handoff_version||!w.catalog->task_static_assets_enabled||!w.tasks.static_assets||w.catalog->task_message_returns||w.tasks.message_returns||!state(w))return common_failure("TaskPersonalCancellationOriginalSourcesRequired");if(w.catalog->task_message_handoff_version==4&&(!w.catalog->task_personal_reports||!w.tasks.personal_reports))return common_failure("TaskPersonalCancellationOriginalSourcesRequired");return validate_task_personal_cancellation_extension_pair(*w.catalog->task_personal_cancellations,w.catalog->task_extensions.get());}
}
TaskPersonalCancellationWorldAccess::TaskPersonalCancellationWorldAccess(const WorldBundle& w,std::shared_ptr<TaskPersonalMessageWorldAccess> delivery):delivery_(std::move(delivery)),services_{{delivery_->services().sources,*w.catalog->task_personal_cancellations,*state(w)},delivery_->services().interaction,delivery_->services().interaction_access}{services_.sources.player_before=[&w](Integer tick,const StableId& fact){return task_personal_cancellation_player_before(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,fact);};}
Outcome<std::shared_ptr<TaskPersonalCancellationWorldAccess>> TaskPersonalCancellationWorldAccess::create(const WorldBundle& w,const DynamicStepInput* phase,const CharacterConditionWorldRead* original_body){if(!w.catalog->task_personal_cancellations){if(state(w))return {false,{},common_failure("TaskPersonalCancellationProfileMismatch").error};return {true,nullptr,{}};}auto valid=ready(w);if(!valid.ok)return {false,{},valid.error};auto delivery=TaskPersonalMessageWorldAccess::create(w,phase,original_body);if(!delivery.ok)return {false,{},delivery.error};if(!delivery.value)return {false,{},common_failure("TaskPersonalCancellationOriginalSourcesRequired").error};return {true,std::shared_ptr<TaskPersonalCancellationWorldAccess>(new TaskPersonalCancellationWorldAccess(w,std::move(delivery.value))),{}};}
Status validate_task_personal_cancellation_world(const WorldBundle& w,const CharacterConditionWorldRead* original_body){auto valid=validate_task_personal_cancellation_layout(w.common,w.catalog->identity.module_versions,state(w));if(!valid.ok)return valid;if(bool(w.catalog->task_personal_cancellations)!=bool(state(w)))return common_failure("TaskPersonalCancellationProfileMismatch");auto holder=TaskPersonalCancellationWorldAccess::create(w,nullptr,original_body);if(!holder.ok)return {false,{},holder.error};return holder.value?validate_task_personal_cancellations(holder.value->services().sources):common_success();}
Status task_personal_cancellation_npc_command_allowed(const StableId& kind){return kind==task_personal_cancellation_command?common_failure("TaskPersonalCancellationOuterResultRequired"):common_success();}
Outcome<TaskPersonalCancellationQuote> preview_task_personal_cancellation_world(const WorldBundle& w,const StableId& actor,const TaskPersonalCancel& command,const CharacterConditionWorldRead* original_body){auto holder=TaskPersonalCancellationWorldAccess::create(w,nullptr,original_body);if(!holder.ok)return {false,{},holder.error};if(!holder.value)return {false,{},common_failure("TaskPersonalCancellationProfileRequired").error};auto execution=PoliticalTakeoverExecutionWorldAccess::create(w);if(!execution.ok)return {false,{},execution.error};auto services=holder.value->services();services.execution=execution.value->tasks();return preview_task_personal_cancellation(services,actor,command);}
Outcome<StableId> apply_task_personal_cancellation_world(WorldBundle& w,const StableId& actor,const TaskPersonalCancel& command,const TaskPersonalCancellationQuote& quote,const CharacterConditionWorldRead* original_body){auto holder=TaskPersonalCancellationWorldAccess::create(w,nullptr,original_body);if(!holder.ok)return {false,{},holder.error};if(!holder.value)return {false,{},common_failure("TaskPersonalCancellationProfileRequired").error};auto execution=PoliticalTakeoverExecutionWorldAccess::create(w);if(!execution.ok)return {false,{},execution.error};auto services=holder.value->services();services.execution=execution.value->tasks();return apply_task_personal_cancellation_in_candidate(w.common,w.tasks,*w.tasks.personal_cancellations,services,actor,command,quote);}
Outcome<BoundaryValue> query_task_personal_cancellations_world(const WorldBundle& w,Integer cursor,const CharacterConditionWorldRead* original_body){if(!w.catalog->task_personal_cancellations)return {true,boundary::obj({{"ok",BoundaryValue{true}},{"enabled",BoundaryValue{false}}}),{}};auto holder=TaskPersonalCancellationWorldAccess::create(w,nullptr,original_body);if(!holder.ok)return {false,{},holder.error};auto execution=PoliticalTakeoverExecutionWorldAccess::create(w);if(!execution.ok)return {false,{},execution.error};auto services=holder.value->services();services.execution=execution.value->tasks();return query_task_personal_cancellations(services,cursor);}
Outcome<StableId> task_personal_cancellation_new_result_world(const WorldBundle& before,const WorldBundle& after,const StableId& actor,const StableId& kind,const ReceiptDetails& details){if(!after.catalog->task_personal_cancellations){if(before.catalog->task_personal_cancellations||state(before)||state(after)||kind==task_personal_cancellation_command)return {false,{},common_failure("TaskPersonalCancellationProfileMismatch").error};return {true,{},{}};}auto valid=ready(before);if(!valid.ok)return {false,{},valid.error};valid=ready(after);if(!valid.ok)return {false,{},valid.error};if(kind==task_personal_cancellation_command&&before.common.tick()!=after.common.tick())return {false,{},common_failure("TaskPersonalCancellationStableCommandRequired").error};return task_personal_cancellation_new_result_source(*state(before),*state(after),actor,kind,details,after.common.tick());}
Status bind_task_personal_cancellation_result_world(WorldBundle& w,const StableId& fact,const StableId& actor,Integer request,const CommitResult& result,const CharacterConditionWorldRead* original_body){if(!w.catalog->task_personal_cancellations)return fact.empty()&&result.kind!=task_personal_cancellation_command?common_success():common_failure("TaskPersonalCancellationProfileRequired");return bind_task_personal_cancellation_result(w.common,*w.tasks.personal_cancellations,fact,actor,request,result);}
}
